#include "app.h"
#include "app_cfg.h"
#include "main.h"
#include <string.h>

/* Private task control blocks and stacks. */
static OS_TCB  AppTaskLed1TCB;
static OS_TCB  AppTaskLed2TCB;
static OS_TCB  AppTaskUartTCB;

static CPU_STK AppTaskLed1Stk[APP_TASK_LED1_STK_SIZE];
static CPU_STK AppTaskLed2Stk[APP_TASK_LED2_STK_SIZE];
static CPU_STK AppTaskUartStk[APP_TASK_UART_STK_SIZE];

/* UART1 is generated by CubeMX in main.c. */
extern UART_HandleTypeDef huart1;

static void AppTaskLed1(void *p_arg)
{
    OS_ERR err;

    (void)p_arg;

    /* Start the 1 ms OS tick after OSStart() has switched to this task. */
    OS_CPU_SysTickInitFreq(SystemCoreClock);

    while (DEF_TRUE) {
        HAL_GPIO_TogglePin(LED1_GPIO_Port, LED1_Pin);

        /* Task period: 1 s. Each pass flips the LED once. */
        OSTimeDlyHMSM(0u, 0u, 1u, 0u, OS_OPT_TIME_HMSM_STRICT, &err);
        if (err != OS_ERR_NONE) {
            Error_Handler();
        }
    }
}

static void AppTaskLed2(void *p_arg)
{
    OS_ERR err;

    (void)p_arg;

    while (DEF_TRUE) {
        HAL_GPIO_TogglePin(LED2_GPIO_Port, LED2_Pin);

        /* Task period: 3 s. Each pass flips the LED once. */
        OSTimeDlyHMSM(0u, 0u, 3u, 0u, OS_OPT_TIME_HMSM_STRICT, &err);
        if (err != OS_ERR_NONE) {
            Error_Handler();
        }
    }
}

static void AppUartSend(const char *str)
{
    uint16_t len = (uint16_t)strlen(str);
    (void)HAL_UART_Transmit(&huart1, (uint8_t *)str, len, 100u);
}

static void AppTaskUart(void *p_arg)
{
    OS_ERR err;
    /* GBK bytes for "欢迎来到RTOS多任务环境！", so XCOM/GBK terminals
       display correctly regardless of the source-file encoding. */
    static const char msg[] =
        "hello uc/OS! "
        "\xBB\xB6\xD3\xAD\xC0\xB4\xB5\xBD"
        "RTOS"
        "\xB6\xE0\xC8\xCE\xCE\xF1\xBB\xB7\xBE\xB3\xA3\xA1"
        "\r\n";

    (void)p_arg;

    while (DEF_TRUE) {
        AppUartSend(msg);

        /* Task period: 2 s. */
        OSTimeDlyHMSM(0u, 0u, 2u, 0u, OS_OPT_TIME_HMSM_STRICT, &err);
        if (err != OS_ERR_NONE) {
            Error_Handler();
        }
    }
}

void App_Init(void)
{
    OS_ERR err;

    OSTaskCreate(&AppTaskLed1TCB,
                 "LED1 Task",
                 AppTaskLed1,
                 (void *)0,
                 APP_TASK_LED1_PRIO,
                 &AppTaskLed1Stk[0],
                 APP_TASK_LED1_STK_LIMIT,
                 APP_TASK_LED1_STK_SIZE,
                 0u,
                 0u,
                 (void *)0,
                 OS_OPT_TASK_STK_CLR,
                 &err);
    if (err != OS_ERR_NONE) {
        Error_Handler();
    }

    OSTaskCreate(&AppTaskLed2TCB,
                 "LED2 Task",
                 AppTaskLed2,
                 (void *)0,
                 APP_TASK_LED2_PRIO,
                 &AppTaskLed2Stk[0],
                 APP_TASK_LED2_STK_LIMIT,
                 APP_TASK_LED2_STK_SIZE,
                 0u,
                 0u,
                 (void *)0,
                 OS_OPT_TASK_STK_CLR,
                 &err);
    if (err != OS_ERR_NONE) {
        Error_Handler();
    }

    OSTaskCreate(&AppTaskUartTCB,
                 "UART Task",
                 AppTaskUart,
                 (void *)0,
                 APP_TASK_UART_PRIO,
                 &AppTaskUartStk[0],
                 APP_TASK_UART_STK_LIMIT,
                 APP_TASK_UART_STK_SIZE,
                 0u,
                 0u,
                 (void *)0,
                 OS_OPT_TASK_STK_CLR,
                 &err);
    if (err != OS_ERR_NONE) {
        Error_Handler();
    }
}
